public ResultData downloadVideo(HttpServletRequest request, HttpServletResponse response,
                                @PathVariable("id") Long id) {
    String userName = casService.getLoginUserName(request);
    log.info("[GET]/productVideoDisplayService/v1/video/{}/download, userName={}", id, userName);
    checkLogin(userName);
    // 先完成鉴权与文件校验并写好响应头，再写文件流；此后异常无法再切回 JSON 错误体
    String fileName;
    try {
        fileName = productVideoDisplayService.checkDownloadAuth(id);
    } catch (Exception e) {
        log.error("download product video auth failed. id: {}", id, e);
        return handleDownloadError(response, e);
    }
    response.setHeader("Content-Disposition", "attachment;filename=" + encodeFileName(request, fileName));
    response.setContentType("application/octet-stream");
    response.setStatus(HttpStatus.OK.value());
    try (OutputStream outputStream = response.getOutputStream()) {
        productVideoDisplayService.streamDownloadFile(id, outputStream);
    } catch (Exception e) {
        // 响应头已发出且可能已写入部分字节，无法再返回 JSON，只能记录日志
        log.error("stream product video failed after response committed. id: {}", id, e);
    }
    return ResultData.ok();
}

public void streamDownloadFile(Long id, OutputStream outputStream) {
    // 二次复查鉴权，防止两个调用之间记录被下架/改回内部
    DocumentInfoEntity entity = queryShelfVideo(id);
    if (!USE_RANGE_EXTERNAL.equals(entity.getUseRange())) {
        log.warn("download product video rejected on stream, state changed. id: {}, useRange: {}",
                id, entity.getUseRange());
        throw ErrorCode.PRODUCT_VIDEO_INTERNAL_NO_DOWNLOAD.throwException();
    }
    String jfrogPath = entity.getJfrogPath();
    String repoName = artifactoryOperationService.getRepoNameByJfrogUrl(jfrogPath);
    if (StringUtils.isBlank(jfrogPath) || StringUtils.isBlank(repoName)) {
        log.error("download product video failed, jfrogPath invalid. id: {}, jfrogPath: {}", id, jfrogPath);
        throw ErrorCode.PRODUCT_VIDEO_STREAM_ERROR.throwException();
    }
    try (InputStream inputStream = artifactoryOperationService.downFileInputStream(repoName, jfrogPath)) {
        StreamUtils.copy(inputStream, outputStream);
        outputStream.flush();
    } catch (Exception e) {
        log.error("download product video stream failed. id: {}, jfrogPath: {}", id, jfrogPath, e);
        throw ErrorCode.PRODUCT_VIDEO_STREAM_ERROR.throwException();
    }
    increaseDownloadNum(entity);
    log.info("download product video success. id: {}, identification: {}", id, entity.getIdentification());
}

/**
 * 查询展示侧可见视频（存在 + 已上架 + 转码成功），不可见按"不存在或已下架"处理
 *
 * @param id 视频记录id
 * @return 视频记录
 */
private DocumentInfoEntity queryShelfVideo(Long id) {
    DocumentInfoEntity entity = documentInfoDao.queryDocumentByIdAndStatusIs1(id);
    boolean visible = entity != null
            && TYPE_PRODUCT_DOCUMENTS.equals(entity.getType())
            && "video".equals(entity.getFileForm())
            && Integer.valueOf(1).equals(entity.getShelfStatus())
            && "success".equals(entity.getProcessState());
    if (!visible) {
        log.warn("product video not visible for display. id: {}", id);
        throw ErrorCode.PRODUCT_VIDEO_NOT_EXIST.throwException();
    }
    return entity;
}
